local function build_routes()
  local routes = {}
  for name, def in pairs(subcommands) do
    composer.register_type("BUFFER_CTX_FORMAT_" .. name:upper(), {
      validate = function(raw)
        return true, raw, nil
      end,
      complete = function(arg_lead)
        local ok, result = pcall(def.complete, arg_lead)
        return (ok and result) or {}
      end,
    })
    routes[#routes + 1] = {
      path = { name },
      args = {
        { name = "a1", type = "BUFFER_CTX_FORMAT_" .. name:upper(), optional = true },
      },
      range = true,
      -- Opt-in per subcommand: a nil `visual` means "any selection", which is
      -- what every subcommand except `column` wants.
      visual = def.visual,
      desc = def.desc,
      run = function(ctx)
        local args = {}
        if ctx.args.a1 ~= nil then
          args[1] = ctx.args.a1
        end
        for _, t in ipairs(ctx.rest) do
          args[#args + 1] = t
        end
        -- ctx.range.range is 0 when no range prefix was given; only then are
        -- line1/line2 meaningless (both default to the cursor line).
        local range_ctx = (ctx.range.range and ctx.range.range > 0)
            and { line1 = ctx.range.line1, line2 = ctx.range.line2 }
          or nil
        local ok, err = pcall(def.handler, args, range_ctx)
        if not ok then
          notify.error(string.format("[%s] %s", name, tostring(err)))
        end
      end,

local function to_roman(n)
  if type(n) ~= "number" or n < 1 then
    return tostring(n)
  end
  local vals = { 1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1 }
  local syms = { "m", "cm", "d", "cd", "c", "xc", "l", "xl", "x", "ix", "v", "iv", "i" }
  local buf = {}
  for i, v in ipairs(vals) do
    while n >= v do
      buf[#buf + 1] = syms[i]
      n = n - v
    end
  end
  return table.concat(buf)
end

local function change_case(text, mode)
  if mode == "sentence" then
    local r = text:lower()
    r = r:gsub("^%l", string.upper)
    r = r:gsub("([.!?]%s+)(%l)", function(p, l)
      return p .. l:upper()
    end)
    return r
  end
  if ok_lib_case then
    return lib_change_case.change_case(text, mode)
  end
  if mode == "upper" then
    return text:upper()
  elseif mode == "lower" then
    return text:lower()
  elseif mode == "title" then
    return (text:gsub("(%a)([%w_']*)", function(f, r)
      return f:upper() .. r:lower()
    end))
  end
  return text
end

